 ## Unreleased

 - Show stock on hand in `GET /items`.
+- Fix: using stock (cooking, consuming) now takes the batch that expires first
+  (FEFO) instead of the most recently received one.

 ## 2.3.0 - 2026-10-20

diff --git a/src/domain/batches.js b/src/domain/batches.js
index ee14fde..f3b963e 100644
--- a/src/domain/batches.js
+++ b/src/domain/batches.js
@@ -18,9 +18,18 @@ export function getBatch(store, id) {
   return batch;
 }

-// The order in which an item's batches are used up.
+// The order in which an item's batches are used up (FEFO, see docs/DATA.md):
+// earliest expiry first, batches without expiry last, then earliest
+// received, then lowest id.
 function consumptionOrder(batches) {
-  return [...batches].sort((a, b) => b.receivedOn.localeCompare(a.receivedOn));
+  return [...batches].sort((a, b) => {
+    if (a.expires !== b.expires) {
+      if (!a.expires) return 1;
+      if (!b.expires) return -1;
+      return a.expires.localeCompare(b.expires);
+    }
+    return a.receivedOn.localeCompare(b.receivedOn) || a.id - b.id;
+  });
 }

