+  const { cook } = await import("../src/domain/recipes.js");
+  const store = fresh();
+  // Milk: HD-1026 (id 3) expires 2026-11-02, HD-1022 (id 4) expires 2026-10-29.
+  const result = cook(store, 2, 10, { at });
+  const milk = result.find((r) => r.itemId === 2);
+  assert.deepEqual(milk.batches, [{ batchId: 4, qty: 2 }]);
+  assert.equal(store.data.batches.find((b) => b.id === 4).qty, 0);
+  assert.equal(store.data.batches.find((b) => b.id === 3).qty, 8);
